// Author: MiYu. Original quest frames, skin textures and localized labels render dynamic quest state and scrolling.
#include "quest_dialog.h"
#include <algorithm>
#include <cmath>

namespace war3 {
namespace {
constexpr const char* member="UI\\FrameDef\\UI\\QuestDialog.fdf";
bool hit(GlueScreen::Rect r,float x,float y){return x>=r.x && y>=r.y && x<r.x+r.w && y<r.y+r.h;}
std::string prefix(unsigned column,unsigned row){return "QuestRow"+std::to_string(column)+"_"+std::to_string(row);}
GlueScreen::Rect scrollTrack(GlueScreen::Rect r,float rightOffset=-.007f){return {r.x+r.w+rightOffset,r.y,.012f,r.h};}
}
QuestDialog::QuestDialog(ScriptSession& session,Images& images,Renderer& renderer,Text& text) : session_(session),renderer_(renderer),screen_(session.world()->resources(),images,renderer,text,member,"QuestDialog") {
    auto bounds=screen_.bounds("QuestDialog");screen_.place("QuestDialog",{(.8f-bounds.w)/2,(.6f-bounds.h)/2,bounds.w,bounds.h});screen_.setText("QuestTitleValue",screen_.localized("QUESTS"));screen_.setText("QuestSubtitleValue",session.config().name);capacity_=std::clamp(unsigned(screen_.bounds("QuestMainContainer").h/.033f),1u,16u);for(unsigned column=0;column<2;++column)for(unsigned row=0;row<capacity_;++row)screen_.attach(member,"QuestListItem",column?"QuestOptionalContainer":"QuestMainContainer",prefix(column,row));screen_.visible("QuestDisplay",false);session_.acknowledgeQuests();sync();
}
GlueScreen::Rect QuestDialog::descriptionBounds() const {auto items=screen_.bounds("QuestItemListContainer"),backdrop=screen_.bounds("QuestDisplayBackdrop");return {items.x+.003f,items.y+items.h,backdrop.w-.02f,std::max(0.f,backdrop.y+backdrop.h-.02f-items.y-items.h)};}
void QuestDialog::sync() {
    for(auto& list:lists_)list.clear();for(auto& [id,quest]:session_.quests())if(quest->enabled && quest->discovered)lists_[quest->required?0:1].push_back(id);bool selected=false;for(auto& list:lists_)if(std::find(list.begin(),list.end(),selected_)!=list.end())selected=true;if(!selected){selected_=!lists_[0].empty()?lists_[0].front():!lists_[1].empty()?lists_[1].front():0;itemScroll_=textScroll_=0;}
    buttons_.clear();for(unsigned column=0;column<2;++column){auto& list=lists_[column];scroll_[column]=std::min(scroll_[column],list.size()>capacity_?list.size()-capacity_:0);auto container=screen_.bounds(column?"QuestOptionalContainer":"QuestMainContainer");for(unsigned row=0;row<capacity_;++row){auto context=prefix(column,row);bool visible=scroll_[column]+row<list.size();screen_.visible(context+"/QuestListItem",visible);if(!visible)continue;auto id=list[scroll_[column]+row];auto& quest=*session_.quests().at(id);float y=container.y+row*.033f;screen_.place(context+"/QuestListItem",{container.x,y,container.w,.033f});screen_.place(context+"/QuestListItemButton",{container.x+.032f,y,container.w-.032f,.033f});screen_.place(context+"/QuestListItemTitle",{container.x+.036f,y+.002f,container.w-.04f,.017f});screen_.setText(context+"/QuestListItemTitle",quest.title);screen_.setText(context+"/QuestListItemComplete",quest.failed?screen_.localized("QUESTFAILED"):quest.completed?screen_.localized("QUESTCOMPLETED"):"");screen_.visible(context+"/QuestListItemIconContainer",!quest.icon.empty());if(!quest.icon.empty())screen_.image(context+"/QuestListItemIconContainer",quest.icon);buttons_[context+"/QuestListItemButton"]=id;}}
    if(selected_){auto& quest=*session_.quests().at(selected_);auto count=quest.items.size();itemScroll_=std::min(itemScroll_,count>4?count-4:0);if(measured_!=selected_ || revision_!=session_.questRevision()){auto lines=screen_.textLines("QuestDisplay",quest.description,descriptionBounds());textLines_=lines.first;textVisible_=lines.second;measured_=selected_;}textScroll_=std::min(textScroll_,textLines_>textVisible_?textLines_-textVisible_:0);}else{measured_=0;textLines_=textVisible_=textScroll_=0;}screen_.setText("QuestDetailsTitle",selected_?session_.quests().at(selected_)->title:std::string{});revision_=session_.questRevision();
}
bool QuestDialog::scrollBar(const UiInput& input,GlueScreen::Rect container,size_t count,size_t visible,size_t& offset,float rightOffset) {
    if(count<=visible)return false;constexpr float width=.012f,thumb=.016f;auto track=scrollTrack(container,rightOffset);auto maximum=count-visible;offset=std::min(offset,maximum);bool active=(input.down || input.pressed) && hit(track,input.startX,input.startY);if(active){float travel=std::max(0.f,track.h-thumb);float position=travel>0?std::clamp((input.y-track.y-thumb/2)/travel,0.f,1.f):0.f;offset=std::min(maximum,size_t(std::lround(position*double(maximum))));}screen_.backdropAt("EscMenuScrollBarBackdrop",track);float travel=std::max(0.f,track.h-thumb);screen_.backdropAt("EscMenuScrollThumbButtonBackdrop",{track.x+(width-thumb)/2,track.y+travel*float(offset)/float(maximum),thumb,thumb});return active;
}
bool QuestDialog::draw(const UiInput& input) {
    if(input.key==VK_ESCAPE || input.key==VK_F9)return false;if(revision_!=session_.questRevision())sync();if(input.wheel){bool changed=false;for(unsigned column=0;column<2;++column)if(hit(screen_.bounds(column?"QuestOptionalContainer":"QuestMainContainer"),input.x,input.y)){auto maximum=lists_[column].size()>capacity_?lists_[column].size()-capacity_:0;scroll_[column]=size_t(std::clamp(std::int64_t(scroll_[column])-input.wheel,std::int64_t(0),std::int64_t(maximum)));changed=true;}if(selected_){auto& quest=*session_.quests().at(selected_);if(hit(screen_.bounds("QuestItemListContainer"),input.x,input.y)){auto maximum=quest.items.size()>4?quest.items.size()-4:0;itemScroll_=size_t(std::clamp(std::int64_t(itemScroll_)-input.wheel,std::int64_t(0),std::int64_t(maximum)));}else if(hit(descriptionBounds(),input.x,input.y) || hit(scrollTrack(descriptionBounds(),.003f),input.x,input.y)){auto maximum=textLines_>textVisible_?textLines_-textVisible_:0;textScroll_=size_t(std::clamp(std::int64_t(textScroll_)-input.wheel,std::int64_t(0),std::int64_t(maximum)));}}if(changed)sync();}
    std::set<std::string> enabled{"QuestAcceptButton"};for(auto& [button,id]:buttons_)enabled.insert(button);renderer_.rect(0,0,float(renderer_.width()),float(renderer_.height()),0x88000000);auto filtered=input;for(unsigned column=0;column<2;++column){auto container=screen_.bounds(column?"QuestOptionalContainer":"QuestMainContainer");if(lists_[column].size()>capacity_ && (input.down || input.pressed) && hit(scrollTrack(container),input.startX,input.startY))filtered.pressed=false;}if(selected_){auto container=screen_.bounds("QuestItemListContainer");if(session_.quests().at(selected_)->items.size()>4 && (input.down || input.pressed) && hit(scrollTrack(container),input.startX,input.startY))filtered.pressed=false;if(textLines_>textVisible_ && (input.down || input.pressed) && hit(scrollTrack(descriptionBounds(),.003f),input.startX,input.startY))filtered.pressed=false;}auto action=screen_.draw("QuestDialog",filtered,enabled);if(action=="QuestAcceptButton")return false;if(auto found=buttons_.find(action);found!=buttons_.end()){selected_=found->second;itemScroll_=textScroll_=0;sync();}
    for(auto& [button,id]:buttons_){auto& quest=*session_.quests().at(id);if(id==selected_ || quest.completed || quest.failed)screen_.highlightAt(quest.failed?"QuestListItemFailedHighlight":quest.completed?"QuestListItemCompletedHighlight":"QuestListItemSelectedHighlight",screen_.bounds(button));}
    if(selected_){auto& quest=*session_.quests().at(selected_);auto items=screen_.bounds("QuestItemListContainer");for(unsigned row=0;row<4 && itemScroll_+row<quest.items.size();++row){auto& item=*quest.items[itemScroll_+row].second;GlueScreen::Rect r{items.x,items.y+row*.014f,.012f,.012f};screen_.checkAt("QuestCheckBox2",r,item.completed);screen_.textAt("QuestItemListItemTitle",item.description,{r.x+.016f,r.y,items.w-.02f,.014f},true,false,true,.011f);}auto description=descriptionBounds();scrollBar(input,description,textLines_,textVisible_,textScroll_,.003f);screen_.textAt("QuestDisplay",quest.description,description,true,false,true,0,textScroll_);}
    bool changed=false;for(unsigned column=0;column<2;++column){auto previous=scroll_[column];scrollBar(input,screen_.bounds(column?"QuestOptionalContainer":"QuestMainContainer"),lists_[column].size(),capacity_,scroll_[column]);changed|=previous!=scroll_[column];}if(selected_)scrollBar(input,screen_.bounds("QuestItemListContainer"),session_.quests().at(selected_)->items.size(),4,itemScroll_);if(changed)sync();return true;
}
}
